import json, sys
sys.path.insert(0, 'tmp')
import ref
import importlib.util
spec = importlib.util.spec_from_file_location("m", "/workspace/submission/main.py")
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)

doc = json.load(open('tmp/fail_32.json'))
ixps, rib, priors, declared, order_pairs, queries = ref.validate(doc)
agg = {}
for p, c in rib:
    q = ref.norm(p, ixps)
    if len(q) < 2 or len(set(q)) != len(q): continue
    t = tuple(q)
    agg[t] = agg.get(t, 0) + c
final, rounds, links = ref.peel_ref(agg)
core = sorted(k for k in links if k not in rounds)
idx = {e: i for i, e in enumerate(core)}
mm = len(core)
order_idx = [idx[p] for p in order_pairs]

# main's build_factors scopes
factors, scopes = m.build_factors(final, idx, mm)
print('main scopes:')
for e in range(mm):
    print(core[e], [core[v] for v in scopes[e]])

# ref's scopes
occs, pos = ref.build_occs(final, core)
rscopes = {}
for e in core:
    sc = {e}
    for (p, w, i) in occs[e]:
        if i > 0:
            sc.add(ref.canon(p[i-1], p[i]))
        if i + 2 < len(p):
            sc.add(ref.canon(p[i+1], p[i+2]))
    rscopes[e] = sc
print('same scopes:', all(set(scopes[e]) == {idx[x] for x in rscopes[core[e]]} for e in range(mm)))

# trace main width check
neigh = []
for e in range(mm):
    s = set(scopes[e])
    s.discard(e)
    neigh.append(s)
ok = True
for x in order_idx:
    cur = neigh[x]
    print('eliminate', core[x], 'neighbors', sorted(core[y] for y in cur), len(cur))
    if len(cur) > 4:
        ok = False
        print('  -> MAIN would fail here')
        break
    cl = sorted(cur)
    for i in range(len(cl)):
        a = cl[i]
        for j in range(i+1, len(cl)):
            b = cl[j]
            neigh[a].add(b); neigh[b].add(a)
    for y in cur:
        neigh[y].discard(x)
    neigh[x] = set()
print('main width pass:', ok)

# ref width trace
adj = {e: set() for e in core}
for e, sc in rscopes.items():
    for x in sc:
        for y in sc:
            if x != y:
                adj[x].add(y)
for pair in order_pairs:
    x = pair
    cur = set(adj[x])
    print('REF eliminate', x, 'neighbors', sorted(cur), len(cur))
    if len(cur) > 4:
        print('  -> ref fails here')
        break
    cl = sorted(cur)
    for i in range(len(cl)):
        for j in range(i+1, len(cl)):
            adj[cl[i]].add(cl[j]); adj[cl[j]].add(cl[i])
    for y in cur:
        adj[y].discard(x)
    adj[x] = set()
